import java.lang.management.ManagementFactory;
import java.lang.management.MemoryPoolMXBean;
import java.lang.management.GarbageCollectorMXBean;
import java.util.ArrayList;
import java.util.List;
import java.util.Set;
import java.util.stream.Collectors;

public class Main {
    public static void main(String[] args) {
        // 1. 打印当前收集器的堆池名称
        Set<String> pools = ManagementFactory.getMemoryPoolMXBeans().stream()
            .map(MemoryPoolMXBean::getName)
            .collect(Collectors.toSet());
        System.out.println("heap pools: " + pools);

        // 2. 打印 GC 收集器名称和已收集次数
        List<GarbageCollectorMXBean> gcs = ManagementFactory.getGarbageCollectorMXBeans();
        for (GarbageCollectorMXBean gc : gcs) {
            System.out.println("gc: " + gc.getName() + ", count=" + gc.getCollectionCount()
                + ", time=" + gc.getCollectionTime() + "ms");
        }

        // 3. 分配并持有引用，观察堆使用量变化
        long before = Runtime.getRuntime().totalMemory() - Runtime.getRuntime().freeMemory();
        List<byte[]> live = new ArrayList<>();
        for (int i = 0; i < 16; i++) {
            live.add(new byte[512 * 1024]); // 每个 512KB
        }
        long after = Runtime.getRuntime().totalMemory() - Runtime.getRuntime().freeMemory();

        System.out.println("used: " + before + " -> " + after + " bytes");
        System.out.println("kept: " + live.size() + " arrays, total " + live.stream().mapToInt(a -> a.length).sum() + " bytes");

        // 4. 验证不同收集器池名称差异
        boolean hasYoungPool = pools.stream().anyMatch(n -> n.contains("Eden") || n.contains("Survivor") || n.contains("Young"));
        boolean hasOldPool = pools.stream().anyMatch(n -> n.contains("Old") || n.contains("Tenured"));
        assert hasYoungPool : "expect a young gen pool";
        assert hasOldPool : "expect an old gen pool";
        assert after > before : "used memory should increase";
        assert live.size() == 16;
    }
}
